// texts returns the messages without arguments in lang, nil for a
// language the catalog lacks.
func texts(lang string) *i18n.Texts {
	switch lang {
	case "en":
		return textsEn
	case "zh-Hans":
		return textsZhHans
	}
	return nil
}

// suppliedTexts are the messages without arguments other packages
// supply, by language and index.
var suppliedTexts = map[string]*[numTexts]string{}

// text says the message without arguments at i in the language of msgs,
// else of the languages it falls back to, else of the source.
func (msgs Messages) text(i int) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, textsEn.At(i))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if t := suppliedTexts[lang]; t != nil && t[i] != "" {
			return t[i]
		}
		if lang == "" {
			return textsEn.At(i)
		}
		if t := texts(lang); t != nil {
			if s := t.At(i); s != "" {
				return s
			}
		}
	}
}

// Supply adds the messages t has in lang to the catalog, over its own.
// nsgo writes the calls, in the package that supplies them, which runs
// them as it initializes.
func Supply(lang string, t Translation) {
	if len(t.Texts) > 0 {
		st := suppliedTexts[lang]
		if st == nil {
			st = new([numTexts]string)
			suppliedTexts[lang] = st
		}
		for i, key := range keyOfText {
			if s, ok := t.Texts[key]; ok {
				st[i] = s
			}
		}
	}
	s := supplied[lang]
	if t.Fraction != nil {
		s.Fraction = t.Fraction
	}
	if t.DividedBy != nil {
		s.DividedBy = t.DividedBy
	}
	if t.Binomial != nil {
		s.Binomial = t.Binomial
	}
	if t.SquareRoot != nil {
		s.SquareRoot = t.SquareRoot
	}
	if t.CubeRoot != nil {
		s.CubeRoot = t.CubeRoot
	}
	if t.FourthRoot != nil {
		s.FourthRoot = t.FourthRoot
	}
	if t.Root != nil {
		s.Root = t.Root
	}
	if t.Subscript != nil {
		s.Subscript = t.Subscript
	}
	if t.Squared != nil {
		s.Squared = t.Squared
	}
	if t.Cubed != nil {
		s.Cubed = t.Cubed
	}
	if t.Power != nil {
		s.Power = t.Power
	}
	if t.PreSubscript != nil {
		s.PreSubscript = t.PreSubscript
	}
	if t.PreSuperscript != nil {
		s.PreSuperscript = t.PreSuperscript
	}
	if t.Limits != nil {
		s.Limits = t.Limits
	}
	if t.LowerLimit != nil {
		s.LowerLimit = t.LowerLimit
	}
	if t.UpperLimit != nil {
		s.UpperLimit = t.UpperLimit
	}
	if t.Above != nil {
		s.Above = t.Above
	}
	if t.Below != nil {
		s.Below = t.Below
	}
	if t.AboveAndBelow != nil {
		s.AboveAndBelow = t.AboveAndBelow
	}
	if t.Labeled != nil {
		s.Labeled = t.Labeled
	}
	if t.Accent != nil {
		s.Accent = t.Accent
	}
	if t.AccentBelow != nil {
		s.AccentBelow = t.AccentBelow
	}
	if t.AccentMark != nil {
		s.AccentMark = t.AccentMark
	}
	if t.Overline != nil {
		s.Overline = t.Overline
	}
	if t.Underline != nil {
		s.Underline = t.Underline
	}
	if t.Negated != nil {
		s.Negated = t.Negated
	}
	if t.Canceled != nil {
		s.Canceled = t.Canceled
	}
	if t.CrossedOut != nil {
		s.CrossedOut = t.CrossedOut
	}
	if t.CanceledBackslash != nil {
		s.CanceledBackslash = t.CanceledBackslash
	}
	if t.Slashed != nil {
		s.Slashed = t.Slashed
	}
	if t.Matrix != nil {
		s.Matrix = t.Matrix
	}
	if t.Array != nil {
		s.Array = t.Array
	}
	if t.Cases != nil {
		s.Cases = t.Cases
	}
	if t.Vector != nil {
		s.Vector = t.Vector
	}
	if t.Multiline != nil {
		s.Multiline = t.Multiline
	}
	if t.Row != nil {
		s.Row = t.Row
	}
	if t.Boxed != nil {
		s.Boxed = t.Boxed
	}
	if t.Error != nil {
		s.Error = t.Error
	}
	if t.Equation != nil {
		s.Equation = t.Equation
	}
	if t.Symbol != nil {
		s.Symbol = t.Symbol
	}
	if t.DoubleStruck != nil {
		s.DoubleStruck = t.DoubleStruck
	}
	if t.Bold != nil {
		s.Bold = t.Bold
	}
	if t.Script != nil {
		s.Script = t.Script
	}
	if t.Fraktur != nil {
		s.Fraktur = t.Fraktur
	}
	supplied[lang] = s
	Catalog.Add(lang)
}

// arg is what an argument wrote, marked in the source's message for a
// pseudo locale.
func (msgs Messages) arg(s string) string {
	if msgs.mark {
		return i18n.Arg(s)
	}
	return s
}

