// Matrix says "matrix with {count, plural, one {# row} other {# rows}}: {rows}"
// in the language the app shows under cx.
func Matrix(cx *core.Scope, count int, rows string) string { return For(cx).Matrix(count, rows) }

// Matrix is the package's Matrix in the language of msgs.
func (msgs Messages) Matrix(count int, rows string) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.Matrix(count, rows))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].Matrix; f != nil {
			return f(count, rows)
		}
		switch lang {
		case "", "en":
			var b strings.Builder
			b.WriteString("matrix with ")
			switch i18n.Cardinal("en", float64(count)) {
			case i18n.One:
				b.WriteString(msgs.arg(i18n.FormatNumber("en", float64(count))))
				b.WriteString(" row")
			default:
				b.WriteString(msgs.arg(i18n.FormatNumber("en", float64(count))))
				b.WriteString(" rows")
			}
			b.WriteString(": ")
			b.WriteString(msgs.arg(rows))
			return b.String()
		case "zh-Hans":
			return i18n.FormatNumber("zh-Hans", float64(count)) + "行矩阵：" + rows
		}
	}
}

