// Part of a formula that could not be read, with its source.
func Error(cx *core.Scope, source string) string { return For(cx).Error(source) }

// Error is the package's Error in the language of msgs.
func (msgs Messages) Error(source string) string {
	if i18n.IsPseudo(msgs.lang) {
		return i18n.Pseudo(msgs.lang, Messages{lang: Source, mark: true}.Error(source))
	}
	for lang := msgs.lang; ; lang = i18n.Parent(lang) {
		if f := supplied[lang].Error; f != nil {
			return f(source)
		}
		switch lang {
		case "", "en":
			return "error: " + msgs.arg(source)
		case "zh-Hans":
			return "错误：" + source
		}
	}
}

